head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL16505";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — editAvailYn, regYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16505.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_41_txt", fn: function(){ return ((dma_educationList.get("roomTpCd") ?? (() => { throw new Error("unresolved:" + "educationList.roomTpCd"); })()) === '1'); } }, { id: "c_otherwise_42", fn: function(){ return (!(((dma_educationList.get("roomTpCd") ?? (() => { throw new Error("unresolved:" + "educationList.roomTpCd"); })()) === '1'))); } }, { id: "c_when_66_txt", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_otherwise_67", fn: function(){ return (!(((dma_pageContext.get("editAvailYn") ?? "") !== 'N'))); } }, { id: "c_when_83", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_otherwise_85", fn: function(){ return (!(((dma_pageContext.get("editAvailYn") ?? "") !== 'N'))); } }, { id: "if_editAvailYn", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_when_79", fn: function(){ return ((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'Y'); } }, { id: "c_when_100", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_otherwise_102", fn: function(){ return (!(((dma_pageContext.get("editAvailYn") ?? "") !== 'N'))); } }, { id: "if_editAvailYn_2", fn: function(){ return ((dma_pageContext.get("editAvailYn") ?? "") !== 'N'); } }, { id: "c_when_96", fn: function(){ return ((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'N'); } }, { id: "c_otherwise_115", fn: function(){ return (!(((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'Y') || ((dma_educationList.get("submitYn") ?? (() => { throw new Error("unresolved:" + "educationList.submitYn"); })()) === 'N'))); } }, { id: "img_124", fn: function(){ return ((dma_pageContext.get("regYn") ?? "") === '1'); } }, { id: "c_otherwise_125", fn: function(){ return (!(((dma_pageContext.get("regYn") ?? "") === '1'))); } }, { id: "img_132", fn: function(){ return ((dma_pageContext.get("regYn") ?? "") === '1'); } }, { id: "c_otherwise_133", fn: function(){ return (!(((dma_pageContext.get("regYn") ?? "") === '1'))); } }, { id: "img_138", fn: function(){ return ((dma_pageContext.get("regYn") ?? "") === '1'); } }, { id: "c_otherwise_139", fn: function(){ return (!(((dma_pageContext.get("regYn") ?? "") === '1'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

