///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: action ?? "/support/eduRspnStaff.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: action ?? "/support/eduRspnStaff.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: action ?? "/support/eduRspnStaff.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name register
 * @description register 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function (_submitYn) {
    if (!scwin.chk()) {
        return;
    }
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerResponsibilityEducation');
    $c.util.getComponent('dma_RegisterReq').set('SCREN_PROCES_TP_CD', "02");
    await scwin.tx_fn_Register('eduRspnStaff.do');
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (_submitYn) {
    if (!scwin.chk()) {
        return;
    }
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'modifyResponsibilityEducation');
    $c.util.getComponent('dma_RegisterReq').set('SCREN_PROCES_TP_CD', "03");
    await scwin.tx_fn_Modify('eduRspnStaff.do');
};

/**
 * @method
 * @name deleteRegisterReq
 * @description delete Register Req 처리
 * @param {*} _disclsEduApplSeq _disclsEduApplSeq
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRegisterReq = async function (_disclsEduApplSeq, _submitYn) {
    if (await $c.win.confirm("삭제 하시겠습니까?") === true) {
        $c.util.getComponent('dma_RegisterReq').set('disclsEduApplSeq', _disclsEduApplSeq);
        $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
        $c.util.getComponent('dma_RegisterReq').set('method', 'removeResponsibilityEducation');
        $c.util.getComponent('dma_RegisterReq').set('SCREN_PROCES_TP_CD', "04");
        await scwin.tx_fn_Delete('eduRspnStaff.do');
    } else {
        return;
    }
};

/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.reset = function () {
    const frm = (document.eduForm || { elements: [] });
    frm.reset();
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function () {
    await $c.win.print();
};

/**
 * @method
 * @name chk
 * @description chk 처리
 * @returns {void}
 * @hidden N
 */
scwin.chk = function () {
    return true;
};
